/**
 * Background tracks in /public/music. The built-in ones are original tracks
 * generated by scripts/make-music.mjs (no licence needed). To add your own,
 * drop an MP3 you have the rights to into public/music and list it here.
 */
export const MUSIC_TRACKS = [
  { id: "sunny-pop", file: "sunny-pop.mp3", label: "Sunny Pop", mood: "bright, happy, everyday city trips and families" },
  { id: "tropical-chill", file: "tropical-chill.mp3", label: "Tropical Chill", mood: "relaxed, beaches, islands, nature, sunsets" },
  { id: "festival-hype", file: "festival-hype.mp3", label: "Festival Hype", mood: "high energy, nightlife, festivals, theme parks, big deals" },
] as const;

export type MusicId = (typeof MUSIC_TRACKS)[number]["id"];
export const MUSIC_IDS = MUSIC_TRACKS.map((t) => t.id) as [MusicId, ...MusicId[]];

export function musicFile(id: string): string {
  return MUSIC_TRACKS.find((t) => t.id === id)?.file ?? "";
}

/** Only plain file names inside /public/music are allowed. */
export const isSafeMusicFile = (file: string) => /^[\w.-]+\.(mp3|m4a|wav|ogg)$/i.test(file);
